ON CONFLICT(feed_url) DO UPDATE SET
  name = excluded.name,
  category = excluded.category,
  site_url = excluded.site_url,
  source_type = excluded.source_type,
  country = excluded.country,
  language = excluded.language,
  trust_level = MAX(editorial_sources.trust_level, excluded.trust_level),
  weight = MAX(editorial_sources.weight, excluded.weight),
  active = 1,
  status = CASE WHEN editorial_sources.status = 'validated' THEN editorial_sources.status ELSE excluded.status END,
  notes = excluded.notes,
  discovered_from = excluded.discovered_from,
  updated_at = CURRENT_TIMESTAMP;
